```python
import re
import re.constants


# Function that matches the action and uses it as the next action.
def play( observations ):
   # Check for a valid action
   regex_pattern = re.compile(r"go|pick|toggle|end")
   match = regex_pattern.search(observations[-1])

   if match:
       return match.group()
   else:
       return None


# Function that handles actions and their usage
def handle_action( observations, action ):
   # Convert the action into a string
   string_action =str(action)

   # Use the action to determine the next observation
   if string_action == 'go':
       if re.search(r'forward', observations[-1]):
           # Use the previous action as the new observation
           try:
               return observations[-2]
           except:
               return None
       elif re.search(r'reverse', observations[-1]):
           try:
               return observations[-3]
           except:
               return None
   elif string_action == 'up':
       if re.search(r'left', observations[-1]):
           try:
               return observations[-2]
           except:
               return None
       elif re.search(r'right', observations[-1]):
           try:
               return observations[-3]
           except:
               return None
   elif string_action == 'down': 
       if re.search(r'left', observations[-1]):
           try:
               return observations[-2]
           except:
               return None
       elif re.search(r'right', observations[-1]):
           try:
               return observations[-3]
           except:
               return None
   elif string_action == 'toggle':
       if re.search(r'crate', observations[-1]):
           result = re.search(r'trowel', observations[-3])
           if result:
               try:
                   return observations[-4]
               except:
                   return None
       elif re.search(r'crate', observations[-1]):
           result = re.search(r'trowel', observations[-2])
           if result:
               try:
                   return observations[-3]
               except:
                   return None
       elif re.search(r'crate', observations[-1]):
           result = re.search(r'trowel', observations[-4])
           if result:
               try:
                   return observations[-5]
               except:
                   return None
   elif string_action == 'end':
       # Use the previous observation as the new action
       return observations[-1]
   else:
       return None


obs_list = ['a wall 1 step forward', 'a wall 3 steps right']
index = 0


while True:
    new_observation = play( obs_list )
    if new_observation:
        if new_observation[0] == 'go':
            obs_list.append(new_observation)
        else:
            obs_list.append(new_observation[:-6])
            index += 1
        print( new_observation[str(index):str(index+5)] )
    else:
        print( new_observation)
